'use server'

import { revalidatePath } from 'next/cache'
import { promises as fs } from 'fs'
import path from 'path'

const dataFilePath = path.join(process.cwd(), 'app/data.json')

export async function toggleNotifications() {
  try {
    const fileContent = await fs.readFile(dataFilePath, 'utf8')
    const data = JSON.parse(fileContent)

    // Toggle the value
    data.notifications = !data.notifications

    // Write back to file
    await fs.writeFile(dataFilePath, JSON.stringify(data, null, 2))

    // Revalidate the path to refresh the page data
    revalidatePath('/')
  } catch (error) {
    console.error('Failed to toggle notifications:', error)
    throw new Error('Failed to toggle notifications')
  }
}

import { promises as fs } from 'fs'
import path from 'path'
import { toggleNotifications } from './actions'

// Function to read the current state
async function getNotificationStatus() {
  try {
    const dataFilePath = path.join(process.cwd(), 'app/data.json')
    const fileContent = await fs.readFile(dataFilePath, 'utf8')
    const data = JSON.parse(fileContent)
    return data.notifications
  } catch (error) {
    console.error('Failed to read notification status:', error)
    return false // Default to false if file read fails
  }
}

export default async function Home() {
  const notificationsEnabled = await getNotificationStatus()

  return (
    <main className="flex min-h-screen flex-col items-center justify-between p-24">
      <div className="z-10 max-w-5xl w-full items-center justify-between font-mono text-sm lg:flex">
        <div className="fixed left-0 top-0 flex w-full justify-center border-b border-gray-300 bg-gradient-to-b from-zinc-200 pb-6 pt-8 backdrop-blur-2xl dark:border-neutral-800 dark:bg-zinc-800/30 dark:from-inherit lg:static lg:w-auto  lg:rounded-xl lg:border lg:bg-gray-200 lg:p-4 lg:dark:bg-zinc-800/30">
          <p className="fixed left-0 top-0 flex w-full justify-center border-b border-gray-300 bg-gradient-to-b from-zinc-200 pb-6 pt-8 backdrop-blur-2xl dark:border-neutral-800 dark:bg-zinc-800/30 dark:from-inherit lg:static lg:w-auto  lg:rounded-xl lg:border lg:bg-gray-200 lg:p-4 lg:dark:bg-zinc-800/30">
            Current Notification Status:&nbsp;
            <code className="font-bold">{notificationsEnabled ? 'ON' : 'OFF'}</code>
          </p>
        </div>
      </div>

      <div className="mb-32 grid text-center lg:max-w-5xl lg:w-full lg:mb-0 lg:grid-cols-4 lg:text-left">
        <form action={toggleNotifications}>
          <button
            type="submit"
            className="group rounded-lg border border-transparent px-5 py-4 transition-colors hover:border-gray-300 hover:bg-gray-100 hover:dark:border-neutral-700 hover:dark:bg-neutral-800/30"
          >
            <h2 className={`mb-3 text-2xl font-semibold`}>
              Toggle Notifications{' '}
              <span className="inline-block transition-transform group-hover:translate-x-1 motion-reduce:transform-none">
                -&gt;
              </span>
            </h2>
            <p className={`m-0 max-w-[30ch] text-sm opacity-50`}>
              Click here to switch your notification preference to {notificationsEnabled ? 'OFF' : 'ON'}.
            </p>
          </button>
        </form>
      </div>
    </main>
  )
}

